            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Standard Radiotherapy Arm (45 Gy BID)",
              "type": "ACTIVE_COMPARATOR",
              "description": "Patients in this group will receive concurrent chemoradiotherapy consisting of cisplatin and etoposide with standard-dose thoracic radiotherapy: 45 Gy administered in 30 fractions of 1.5 Gy twice daily (BID).",
              "interventionNames": [
                "Radiation: Thoracic Radiotherapy 45 Gy BID"
              ]
            },
            {
              "label": "Escalated Dose Radiotherapy Arm (60 Gy BID)",
              "type": "EXPERIMENTAL",
              "description": "Patients in this group will receive the same chemotherapy as Arm 1, combined with an escalated thoracic radiotherapy dose: 60 Gy delivered in 40 fractions of 1.5 Gy twice daily (BID). Dose may be reduced to 54 Gy if organs at risk exceed tolerance.",
              "interventionNames": [
                "Radiation: Thoracic Radiotherapy 60 Gy BID"
              ]
            },
            {
              "label": "Simultaneous Integrated Boost Radiotherapy Arm (45-54 Gy BID)",
              "type": "EXPERIMENTAL",
              "description": "Patients in this group will receive the same chemotherapy as in other arms, with thoracic radiotherapy delivered as a simultaneous integrated boost (SIB): 45 Gy to the general target volume and 54 Gy to the high-risk clinical target volume (CTV) in 30 fractions BID.",
              "interventionNames": [
                "Radiation: Thoracic Radiotherapy SIB 45-54 Gy BID"
              ]
            }
          ],
          "interventions": [
            {
              "type": "RADIATION",
              "name": "Thoracic Radiotherapy 45 Gy BID",
              "description": "45 Gy delivered in 30 fractions of 1.5 Gy twice daily over three weeks, with 95% of the planning target volume (PTV) receiving at least 95% of the prescribed dose.",
              "armGroupLabels": [
                "Standard Radiotherapy Arm (45 Gy BID)"
              ]
            },
            {
              "type": "RADIATION",
              "name": "Thoracic Radiotherapy 60 Gy BID",
              "description": "60 Gy delivered in 40 fractions of 1.5 Gy BID. A minimum dose of 54 Gy will be accepted if organ-at-risk tolerance is exceeded.",
              "armGroupLabels": [
                "Escalated Dose Radiotherapy Arm (60 Gy BID)"
              ]
            },
            {
              "type": "RADIATION",
              "name": "Thoracic Radiotherapy SIB 45-54 Gy BID",
              "description": "45 Gy in 30 fractions (1.5 Gy BID) to PTV and 54 Gy in 30 fractions (1.8 Gy BID) to high-risk CTV. Both delivered simultaneously using 3D conformal planning.",
              "armGroupLabels": [
                "Simultaneous Integrated Boost Radiotherapy Arm (45-54 Gy BID)"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Progression-Free Survival (PFS)",
              "description": "Progression-Free Survival (PFS) is defined as the time from randomization to documented disease progression based on RECIST 1.1 criteria or death from any cause. Patients will be evaluated at baseline, every 3 months for the first 2 years, then every 6 months up to year 5 using imaging and clinical assessment.",
              "timeFrame": "From date of randomization until disease progression or death, whichever occurs first, assessed up to 5 years"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Overall Survival (OS)",
              "description": "Overall Survival (OS) is defined as the time from randomization to death from any cause. Patients will be followed longitudinally through scheduled clinical visits and survival status checks",
              "timeFrame": "From date of randomization until death from any cause, assessed up to 5 years"
            },
            {
              "measure": "Incidence of Acute and Late Toxicities (per CTCAE v4.0)",
              "description": "Toxicity will be assessed using the Common Terminology Criteria for Adverse Events (CTCAE) version 4.0. Both acute and late toxicities (e.g., esophagitis, pneumonitis, hematologic toxicity) will be recorded during treatment and follow-up.",
              "timeFrame": "From treatment initiation through 5-year follow-up"
            },
            {
              "measure": "Quality of Life Assessment (EORTC QLQ-C30)",
              "description": "Quality of life will be measured using the EORTC QLQ-C30. Changes in scores over time will be analyzed to evaluate treatment impact on physical, emotional, and functional well-being. The EORTC QLQ-C30 (European Organisation for Research and Treatment of Cancer Quality of Life Questionnaire-Core 30) is a validated instrument designed to assess the quality of life of cancer patients. It includes 30 items organized into multi-item scales and single-item measures, covering a range of functional domains, symptoms, and overall health status. All items are scored on a 1 to 4 Likert scale (1 = \"Not at all\" to 4 = \"Very much\"), except for the two items of the global health status/QoL scale, which are scored from 1 to 7 (1 = \"Very poor\" to 7 = \"Excellent\").\n\nA high score on a functional scale reflects better functioning. A high score on a symptom scale reflects worse symptom severity. A high global health/QoL score indicates overall good health and quality of life as perceived by the patient.",
              "timeFrame": "Baseline, 3 months, 6 months, 12 months, and annually up to 5 years"
            },
            {
              "measure": "Quality of life Assesment (LC13)",
              "description": "Quality of life will be measured using lung cancer-specific module LC13. Changes in scores over time will be analyzed to evaluate treatment impact on physical, emotional, and functional well-being. The EORTC QLQ-LC13 is a lung cancer-specific module designed to be used in conjunction with the EORTC QLQ-C30. It focuses on lung cancer-related symptoms and treatment side effects, particularly from chemotherapy and radiotherapy. Just like with the QLQ-C30, raw scores are linearly transformed to a 0-100 scale for each item or symptom scale. Higher scores always reflect worse symptoms or more severe treatment-related side effects. A change of ≥10 points is typically considered clinically meaningful.\n\nCombined with the QLQ-C30, the LC13 enhances sensitivity to lung-specific disease burden and treatment toxicity.",
              "timeFrame": "Baseline, 3 months, 6 months, 12 months, and annually up to 5 years"
            },
            {
              "measure": "Quality of Life Assesment (LC29)",
              "description": "Quality of life will be measured using the lung cancer-specific module LC29. Changes in scores over time will be analyzed to evaluate treatment impact on physical, emotional, and functional well-being. The EORTC QLQ-LC29 is a lung cancer-specific quality of life questionnaire, that captures a broader and more contemporary range of lung cancer symptoms and treatment-related side effects, especially relevant to newer therapies like immunotherapy and targeted agents. The QLQ-LC29 is designed to be used in conjunction with the EORTC QLQ-C30. All items are scored on a 1-4 Likert scale:\n\n1. = Not at all\n2. = A little\n3. = Quite a bit\n4. = Very much Scores are linearly transformed to a 0-100 scale. For all LC29 items and scales: Higher scores indicate more severe symptoms or problems.\n\nLC29 retains some items from LC13 (e.g., cough, dyspnea, pain) but adds new domains (e.g., fear of progression, trouble concentrating). Provides a broader range of symptoms, including psychosocial concerns.",
              "timeFrame": "Baseline, 3 months, 6 months, 12 months, and annually up to 5 years"
            },
            {
              "measure": "Time to First Local or Distant Recurrence",
              "description": "Time to recurrence will be measured based on clinical and radiological evaluations. Recurrences will be categorized as local (within the irradiated field) or distant (outside the thoracic field).",
              "timeFrame": "From randomization until first documented recurrence, assessed up to 5 years"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Histologically confirmed diagnosis of small cell lung cancer (SCLC)\n* Limited-stage disease (Stage I-III; any T, any N, M0), eligible for definitive radiotherapy\n* Measurable disease according to RECIST 1.1\n* Age ≥18 years\n* ECOG performance status 0-2\n* No prior thoracic radiotherapy\n* Signed informed consent\n* Adequate hematologic function: WBC ≥3.0×10⁹/L, neutrophils ≥1.5×10⁹/L, platelets ≥100×10⁹/L, hemoglobin ≥90 g/L\n* Adequate liver and renal function: total bilirubin ≤1.5×ULN, AST/ALT ≤1.5×ULN, creatinine normal or CrCl ≥60 mL/min\n* Pulmonary function: FEV1 \\>1 L or \\>30% predicted; DLCO \\>30% predicted\n\nExclusion Criteria:\n\n* Prior surgery or radiotherapy for any lung cancer (SCLC or NSCLC)\n* Presence of malignant cells in pleural or pericardial effusion\n* Serious uncontrolled systemic disorders (e.g., active infection, unstable cardiovascular disease)\n* Medical, psychological, or social conditions that could interfere with compliance\n* Active malignancy other than SCLC (except localized prostate/breast cancer or basal cell carcinoma)\n* Refusal or inability to sign informed consent",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
