      "resultsSection": {
        "participantFlowModule": {
          "preAssignmentDetails": "Participant Flow refers to the Safety Set-Intravenous (SS-iv).",
          "recruitmentDetails": "The study started to enroll participants in June 2018 and concluded in November 2020.",
          "groups": [
            {
              "id": "FG000",
              "title": "Age Cohort: >=12 to <16 Years",
              "description": "Screening Period (1-10 days): Participants receiving open-label BRV (OLB) or prescribed oral BRV (RxB) continued to receive oral BRV. IOB Treatment Period (2-10 days): Participants who initiated Oral BRV (IOB) continued with oral BRV 2 milligram/kilogram/day (mg/kg/day). IV PK (Intravenous Pharmacokinetic) Period (1-6 days): During iv PK Period, iv BRV was administered every 12 hours. For OLB, RxB, and IOB participants, first iv Brivaracetam (BRV) dose was equivalent to final dose of oral BRV and for Initiating iv BRV (IIB) participants, first iv BRV dose was 1mg/kg. For each cohort, the first half received 15-minute infusion, the remaining half as a bolus (up to 2-minute infusion). Down-Titration Period: Participants who discontinued treatment, had their BRV dose reduced every week for a maximum of 4 weeks down to a dose of 1mg/kg/day."
            },
            {
              "id": "FG001",
              "title": "Age Cohort: >=6 to <12 Years",
              "description": "Screening Period (1-10 days): Participants receiving OLB or RxB continued to receive oral BRV. IOB Treatment Period (2-10 days): IOB Participants continued with oral BRV 2mg/kg/day. IV PK Period (1-6 days): During iv PK Period, iv BRV was administered every 12 hours. For OLB, RxB, and IOB participants, first iv BRV dose was equivalent to final dose of oral BRV and for IIB participants, first iv BRV dose was 1mg/kg. For each cohort, the first half received the 15-minute infusion, the remaining half as a bolus (up to 2-minute infusion). Down-Titration Period: Participants who discontinued treatment, had their BRV dose reduced every week for a maximum of 4 weeks down to a dose of 1mg/kg/day."
            },
            {
