          "officialTitle": "Lexapro for Major Depression in Patients With Epilepsy"
        },
        "statusModule": {
          "statusVerifiedDate": "2018-06",
          "overallStatus": "TERMINATED",
          "whyStopped": "Unable to recruit targeted #",
          "expandedAccessInfo": {
