          "resultsFirstSubmitDate": "2014-12-24",
          "resultsFirstSubmitQcDate": "2015-07-29",
          "resultsFirstPostDateStruct": {
            "date": "2015-08-03",
            "type": "ESTIMATED"
          },
          "lastUpdateSubmitDate": "2018-06-13",
          "lastUpdatePostDateStruct": {
