            "class": "OTHER"
          },
          "briefTitle": "Oxfendazole in Mild Parenchymal Brain Cysticercosis",
          "officialTitle": "A Double-blind Multicenter, Randomized Controlled Trial of Single and Multiple Dose Regimens of Oxfendazole for Mild (One or Two Lesions) Parenchymal Brain Cysticercosis, With an Open Comparison Group"
        },
        "statusModule": {
          "statusVerifiedDate": "2026-04",
          "overallStatus": "NOT_YET_RECRUITING",
          "expandedAccessInfo": {
