        "oversightModule": {
          "isFdaRegulatedDrug": true,
          "isFdaRegulatedDevice": false
        },
        "descriptionModule": {
          "briefSummary": "The goal of this clinical trial is to compare a single and multiple dose regimens of oxfendazole with the standard treatment in patients with mild (one or two lesions) parenchymal brain cysticercosis. The main question it aims to answer is if OXF will enhance clearance of brain parasites and therefore provide greater cysticidal efficacy, with the potential to provide a single-dose therapy for this type of NCC.\n\nThe study cohort will also allow us to identify early imaging markers that predict lesion resolution, as well as factors associated with residual calcification or focal gliosis after lesion resolution. This study will also provide additional information on the safety of the study interventions.",
          "detailedDescription": "This three-arm randomized controlled phase II/III clinical trial will compare the efficacy and safety of a single-dose regimen with 20 mg/kg oxfendazole and a regimen with three similar doses spread over seven days (day 1, day 4 and day 7), with the most effective antiparasitic regimen available, combined albendazole plus praziquantel for ten days in individuals with mild NCC (with one to two lesions).\n\nParticipants will receive treatment with oxfendazole (one or three dose regimens) or the standard treatment (albendazole + praziquantel). At day 15 after treatment onset, an MRI will be performed to evaluate early predictors of lesion resolution. MRI at day 90 will serve to evaluate efficacy (lesion resolution) and a day 180 MRI will evaluate sequelae lesions. CT will be performed at the en of the study to confirm persistence of calcified sequelae lesion.\n\nThe study will enroll 544 patients with viable or degenerating parenchymal NCC with no more than two lesions, all in a single brain area. Lesions can be one or two adjacent, viable or degenerating NCC lesions. Patients with only calcified lesions will not be included even if they show perilesional contrast enhancement."
        },
        "conditionsModule": {
          "conditions": [
            "Brain Cysticercosis"
          ],
          "keywords": [
            "Cysticercosis",
            "Cysticercosis treatment"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "PHASE2",
            "PHASE3"
          ],
          "designInfo": {
            "allocation": "RANDOMIZED",
            "interventionModel": "PARALLEL",
            "interventionModelDescription": "The intervention administered orally will be done randomly, in three groups or arms; arms 1 and 2, receiving oxfendazole (OXF) in a single dose or oxfendazole in three-days regimen (days 1, 4 and 7), respectively; arm 3, receiving a ten days albendazole (ABZ) + praziquantel (PZQ) regimen.",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "DOUBLE",
              "maskingDescription": "This study is a double-blind trial in regards to dose regime of OXF. Neither the investigators nor the subjects know which dose of OXF a given subject is receiving, although subjects and clinical study staff will know whether they are receiving one of the OXF regimes or active ABZ+PZQ.",
              "whoMasked": [
                "PARTICIPANT",
                "INVESTIGATOR"
              ]
            }
          },
          "enrollmentInfo": {
            "count": 544,
            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Intervention 1",
              "type": "EXPERIMENTAL",
              "description": "OXF 20 mg/kg/d, single dose, orally",
              "interventionNames": [
                "Drug: Oxfendazole single dose"
              ]
            },
            {
              "label": "Intervention 2",
              "type": "EXPERIMENTAL",
              "description": "OXF 20 mg/kg/d, for three days (1, 4 and 7), orally",
              "interventionNames": [
                "Drug: Oxfendazole three doses"
              ]
            },
            {
              "label": "Comparison regimen",
              "type": "ACTIVE_COMPARATOR",
              "description": "Combined treatment with albendazole (15 mg/k/d) plus praziquantel (50 mg/k/d), for 10 days, orally.",
              "interventionNames": [
                "Drug: albendazole plus praziquantel regime"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "Oxfendazole single dose",
              "description": "Subjects will receive active oxfendazole, 20 mg/kg/day, orally, as a single dose. Oxfendazole placebo will be used at days 4 and 7 to maintain blinding between the two intervention arms.",
