        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Vigabatrin arm",
              "type": "EXPERIMENTAL",
              "description": "Vigabatrin in capsules co-administered with placebo in liquid.",
              "interventionNames": [
                "Drug: Vigabatrin",
