            }
          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "Vigabatrin",
              "description": "Vigabatrin in capsules administered orally, initially (between V1 and V2) once daily in the evening,and starting from V2 administered two times daily.",
              "armGroupLabels": [
                "Vigabatrin arm"
              ]
            },
            {
              "type": "DRUG",
              "name": "Rapamycin",
              "description": "Rapamycin in liquid administered orally, in the morning, every other day or daily depending on the patient's body weight. The starting dose of rapamycin will be calculated according to the body weight of the patient measured at V1.",
              "armGroupLabels": [
                "Rapamycin arm"
              ]
            },
            {
              "type": "DRUG",
              "name": "Placebo",
              "description": "Placebo in liquid administered orally, once daily, in the morning. The starting dose of placebo in liquid will be calculated according to the body weight of the patient measured at V1.",
              "armGroupLabels": [
