              ],
              "otherNames": [
                "Placebo in liquid"
              ]
            },
            {
              "type": "DRUG",
              "name": "Placebo",
              "description": "Placebo in granules administered orally, initially once daily in the evening,and after reaching the targeted dose administered two times daily.",
              "armGroupLabels": [
                "Rapamycin arm"
              ],
