        "descriptionModule": {
          "briefSummary": "Preliminary Efficacy and Feasibility of Using NeuroCytotron in the Treatment of Autism Spectrum Disorder",
          "detailedDescription": "Experimental, pilot, one-arm, open-label, single-center, 13-month, single-center study to evaluate the effect of NCX neuronal regeneration treatment in subjects with Autism Spectrum Disorder (ASD) to explore the therapeutic effects of NeuroCytonix neuronal regeneration technology on ASD symptoms. Specific objectives include collecting preliminary safety and efficacy data, assessing appropriate dosing, and measuring the impact on participants' quality of life after treatment."
        },
        "conditionsModule": {
          "conditions": [
            "Autism Spectrum Disorder"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "NA"
          ],
          "designInfo": {
            "allocation": "NA",
            "interventionModel": "SINGLE_GROUP",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "NONE"
            }
          },
          "enrollmentInfo": {
            "count": 100,
            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Arm One",
              "type": "EXPERIMENTAL",
              "description": "All participants",
              "interventionNames": [
                "Device: Neurocytotron"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DEVICE",
              "name": "Neurocytotron",
              "description": "Neuronal regeneration treatment",
              "armGroupLabels": [
                "Arm One"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Changes in Autism Diagnostic Observation Schedule-Second Edition scale scores",
              "description": "* Variables related to social communication, such as quality of social interaction, emotional reciprocity, and verbal and nonverbal communication.\n* Variables related to repetitive and stereotyped behavior, such as repetitive motor movements and restricted interests or behaviors.\n* Autism Diagnostic Observation Schedule-Second Edition total score as a global measure of Autism Spectrum Disorder symptoms.\n\nThe Autism Diagnostic Observation Schedule-Second Edition scores range from 0 to 24, where higher scores indicate a greater severity of Autism Spectrum Disorder symptoms",
              "timeFrame": "Through study completion, an average of 1 year"
            },
            {
              "measure": "Changes in Adaptive Behavioral Assessment System scores",
              "description": "* Variables related to adaptive skills in areas such as communication, daily living, personal autonomy and social skills.\n* Total adaptive skills scores to assess overall functioning in different adaptive domains.\n\nThe Autism Diagnostic Observation Schedule-Second Edition scores range from 0 to 24, where higher scores indicate a greater severity of Autism Spectrum Disorder symptoms\n\nThe Adaptive Behavioral Assessment System scores range from 40 to 160, where higher scores indicate better adaptive functioning",
              "timeFrame": "Through study completion, an average of 1 year"
            },
            {
              "measure": "Changes in Childhood Autism Rating Scale scores",
              "description": "* Variables related to the severity of ASD symptoms, including aspects such as social relationship, communication, stereotyped behavior and eye contact.\n* Childhood Autism Rating Scale total score as a global measure of Autism Spectrum Disorder symptom severity.\n\nThe Childhood Autism Rating Scale scores range from 15 to 60, where higher scores indicate a greater severity of autism symptoms",
              "timeFrame": "Through study completion, an average of 1 year"
            },
            {
              "measure": "Changes in Gilliam Autism Measurement Scale score",
              "description": "* Variables related to the severity of ASD symptoms, including areas such as social interaction, communication, stereotyped behaviors, and restricted interests.\n* Specific subscales of the Gilliam Autism Measurement Scale that assess different dimensions of Autism Spectrum Disorder symptoms.\n\nThe Gilliam Autism Measurement Scale scores range from 0 to 174, where higher scores indicate a greater severity of autism symptoms",
              "timeFrame": "Through study completion, an average of 1 year"
            },
            {
              "measure": "Withdrawal Rate",
              "description": "• To assess the study withdrawal rate to NeuroCytotron treatment to determine the feasibility and acceptability of treatment by subjects and caregivers.",
              "timeFrame": "Through study completion, an average of 1 year"
            },
            {
              "measure": "Adherence to Treatment",
              "description": "• To assess the adherence to NeuroCytotron treatment to determine the feasibility and acceptability of treatment by subjects and caregivers.",
              "timeFrame": "Through study completion, an average of 1 year"
            },
            {
              "measure": "Treatment Security",
              "description": "• Record any treatment-related adverse events to assess the safety of NeuroCytotron in this subject population.",
              "timeFrame": "Through study completion, an average of 1 year"
            },
            {
              "measure": "Change in the number of seizures or epileptic seizures during the study period",
              "description": "• Obtain information on the number of seizures (if any) before and after treatment.",
              "timeFrame": "Through study completion, an average of 1 year"
            },
            {
              "measure": "Neurophysiological changes: in functional activity and brain anatomy using Magnetic Resonance Imaging",
              "description": "* Representative, visual, motor, basal ganglia and other modules\n* Total brain volume\n* Frontal and temporal lobe volume\n* Cortical thickness in the frontal lobe\n* Surface area and cortical gyrification and cerebrospinal fluid volume\n* Cerebellum volume\n* Volume of the corpus callosum\n* White matter, hippocampus, amygdala, thalamus, and basal ganglia\n\nThe above describes one assessment where several anatomical regions are imaged via Magnetic Resonance Imaging - sequence T1",
              "timeFrame": "Through study completion, an average of 1 year"
            },
            {
              "measure": "Neurophysiological changes: in functional activity and brain anatomy using Diffusion Tensor Imaging",
              "description": "• Diffusion Tensor Imaging data, as an increase in the values of the anisotropy fractions (AF)",
              "timeFrame": "Through study completion, an average of 1 year"
            },
            {
              "measure": "Neurophysiological changes: in functional activity and brain anatomy using Electroencephalogram",
              "description": "• Brain activities during resting states.",
              "timeFrame": "Through study completion, an average of 1 year"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Changes in comorbid symptoms",
              "description": "Evaluate changes in comorbid symptoms commonly associated with Autism Spectrum Disorder",
              "timeFrame": "Through study completion, an average of 1 year"
            },
            {
              "measure": "Changes in sensory processing: hypersensitivity by percentile ranks",
              "description": "Measurement of changes in sensory processing difficulties, including hypersensitivity, using standardized tools such as the sensory profile by means of Percentile ranks and classifications on the Sensory Profile 2, which will be administered at baseline (pre-treatment) and after 28 days of treatment (post-treatment).\n\nPercentile Ranks: Typical Performance: Scores between the 25th and 75th percentiles. Probable Difference: Scores between the 2nd and 25th percentiles or between the 75th and 98th percentiles. Definite Difference: Scores below the 2nd percentile or above the 98th percentile.\n\nThe scores in each sensory domain and the overall sensory profile will be recorded and analyzed to determine changes in sensory processing difficulties.",
              "timeFrame": "Through study completion, an average of 1 year"
            },
            {
              "measure": "Changes in sensory processing: hypersensitivity by classification scores",
              "description": "Measurement of changes in sensory processing difficulties, including hypersensitivity, using standardized tools such as the sensory profile by means of Percentile ranks and classifications on the Sensory Profile 2, which will be administered at baseline (pre-treatment) and after 28 days of treatment (post-treatment).\n\nClassification Scores: Typical Performance: Indicates that the child's sensory processing is within the expected range for their age. Probable Difference: Suggests that the child's sensory processing is somewhat different from peers, possibly affecting their daily life. Definite Difference: Indicates significant differences in sensory processing that are likely to impact daily functioning.\n\nThe scores in each sensory domain and the overall sensory profile will be recorded and analyzed to determine changes in sensory processing difficulties.",
              "timeFrame": "Through study completion, an average of 1 year"
            },
            {
              "measure": "Changes in sensory processing: hyposensitivity by percentile ranks",
              "description": "Measurement of changes in sensory processing difficulties, including hyposensitivity, using standardized tools such as the sensory profile by means of Percentile ranks and classifications on the Sensory Profile 2, which will be administered at baseline (pre-treatment) and after 28 days of treatment (post-treatment).\n\nPercentile Ranks: Typical Performance: Scores between the 25th and 75th percentiles. Probable Difference: Scores between the 2nd and 25th percentiles or between the 75th and 98th percentiles. Definite Difference: Scores below the 2nd percentile or above the 98th percentile.\n\nThe scores in each sensory domain and the overall sensory profile will be recorded and analyzed to determine changes in sensory processing difficulties.",
              "timeFrame": "Through study completion, an average of 1 year"
            },
            {
              "measure": "Changes in sensory processing: hyposensitivity by classification scores",
              "description": "Measurement of changes in sensory processing difficulties, including hyposensitivity, using standardized tools such as the sensory profile by means of Percentile ranks and classifications on the Sensory Profile 2, which will be administered at baseline (pre-treatment) and after 28 days of treatment (post-treatment).\n\nClassification Scores: Typical Performance: Indicates that the child's sensory processing is within the expected range for their age. Probable Difference: Suggests that the child's sensory processing is somewhat different from peers, possibly affecting their daily life. Definite Difference: Indicates significant differences in sensory processing that are likely to impact daily functioning.\n\nThe scores in each sensory domain and the overall sensory profile will be recorded and analyzed to determine changes in sensory processing difficulties.",
              "timeFrame": "Through study completion, an average of 1 year"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n1. Male or female subjects with a confirmed diagnosis of ASD according to DSM-5 criteria.\n2. Subjects ≥ 3 and ≤ 50 years.\n3. Subjects with ASD severity grade 1 to 3 according to DSM-5 criteria.\n4. To have the informed consent of the parents or legal representatives for the subject's participation in the study.\n5. Subjects must be physically able and willing to undergo the treatment sessions.\n6. Subjects must be medically and psychologically stable to participate in the study.\n\nExclusion Criteria:\n\n1. Presence of medical conditions that could contraindicate the use of NeuroCytotron DM, such as severe neurological disorders and difficult-to-control epilepsy.\n\n   1. uncontrolled epilepsy is defined as: more than 1 generalized seizure in any month within the 3 months prior to the day 1 visit, or\n   2. history of any of the following within 9 months prior to the day 1 visit: prolonged seizures or repetitive seizure activity requiring administration of a rescue benzodiazepine (oral, rectal, etc.) more than once a month, seizures lasting more than 10 minutes, status epilepticus or epilepsy with autonomic involvement.\n2. Concurrent participation in other therapies or interventions for autism during the study period.\n3. Logistical or situational limitations that prevent regular attendance at treatment sessions.\n4. History of significant adverse reactions to similar treatments or involving the use of anesthesia.\n5. Presence of serious behavioral problems or aggression that may affect the safety of the subject or staff during treatment sessions.\n6. Current or recent (previous 14 days) history of clinically significant bacterial, fungal, viral or mycobacterial infection.\n7. Subjects with magnetic implants, pacemakers, claustrophobia or any other condition that prevents them from entering or remaining in the DM NeuroCytotron.",
