          "interventions": [
            {
              "type": "DIAGNOSTIC_TEST",
              "name": "Control Group",
              "description": "The control group receives standard care, which includes routine medical management and general physical rehabilitation exercises. This involves regular consultations with healthcare providers and exercises aimed at maintaining mobility and physical function. The control group also follows a schedule of three 45-minute sessions per week for 12 weeks, ensuring a consistent comparison with the experimental group.",
              "armGroupLabels": [
                "Control Group"
              ]
            },
            {
              "type": "COMBINATION_PRODUCT",
              "name": "Experimental Group",
              "description": "The experimental intervention involves tele-rehabilitation-based task-specific training to enhance cognitive functions in multiple sclerosis (MS) patients. This program includes cognitive exercises targeting memory, attention, executive function, and processing speed, conducted remotely via a tele-rehabilitation platform. Patients participate in three 45-minute sessions per week for 12 weeks. Each session is guided by a trained therapist, ensuring personalized support and real-time feedback.",
              "armGroupLabels": [
                "EXP group"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Montreal Cognitive Assessment (MoCA) scale",
              "description": "The MoCA scale is a comprehensive tool designed to evaluate various cognitive domains, including attention and concentration, executive functions, memory, language, visuospatial skills, conceptual thinking, calculations, and orientation. It provides a detailed assessment of cognitive performance, making it an ideal measure for tracking cognitive improvements in MS patients participating in the tele-rehabilitation and task-specific training programs.",
              "timeFrame": "12 Months"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Individuals with a diagnosis of MS confirmed by a neurologist.\n* Between 18 and 65 years of age.\n* Presence of psychosis confirmed by standardized psychometric testing.\n* A stable treatment environment that allows intervention.\n* Internet access with camera and computer/tablet.\n* Ability to understand and follow course directions.\n* Willingness to give informed consent.\n\nExclusion Criteria:\n\n* Severe psychiatric co-morbidities affecting cognitive function.\n* Concurrent intervention with other psychological rehabilitation programs.\n* Lack of availability or use of technology necessary for tele-rehabilitation.\n* Further research interventions.\n* Unstable medical condition",
