        "descriptionModule": {
          "briefSummary": "The National Registry of Genetically Triggered Thoracic Aortic Aneurysms and Cardiovascular Conditions (GenTAC) was initiated in 2006 by the National Heart, Lung, and Blood Institute (NHLBI) and the National Institute of Arthritis and Musculoskeletal and Skin Diseases (NIAMS). GenTAC established a registry of 3706 patients with genetic conditions that may be related to thoracic aortic aneurysms and collected medical data and biologic samples. The study ended in September 2016. Data and samples are available from NHLBI and requests should be made to BioLINCC. See the NHLBI website for more information: https://www.nhlbi.nih.gov/research/resources/gentac/."
        },
        "conditionsModule": {
          "conditions": [
            "Marfan Syndrome",
            "Turner Syndrome",
            "Ehlers-Danlos Syndrome",
            "Loeys-Dietz Syndrome",
            "FBN1, TGFBR1, TGFBR2, ACTA2 or MYH11 Genetic Mutation",
            "Bicuspid Aortic Valve Without Known Family History",
            "Bicuspid Aortic Valve With Family History",
            "Bicuspid Aortic Valve With Coarctation",
            "Familial Thoracic Aortic Aneurysm and Dissections",
            "Shprintzen-Goldberg Syndrome",
            "Other Aneur/Diss of Thoracic Aorta Not Due to Trauma, <50yo",
            "Other Congenital Heart Disease"
          ],
          "keywords": [
