        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Thoracic aortic aneurysms and dissections and their associated surgical interventions",
              "timeFrame": "bi-annual"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Eligible subjects must have one of the conditions listed below and be enrolled in-person at one of the participating clinical centers.Contact the study coordinator at the location nearest you for more information about participation.\n\n* Marfan syndrome\n* Turner syndrome\n* Ehlers-Danlos syndrome\n* Loeys-Dietz syndrome\n* FBN1, TGFBR1, TGFBR2, ACTA2 or MYH11 genetic mutation\n* Bicuspid aortic valve without known family history\n* Bicuspid aortic valve with family history\n* Bicuspid aortic valve with coarctation\n* Familial Thoracic Aortic Aneurysm and DissectionsYes\n* Shprintzen-Goldberg syndrome\n* Other aneurysms and dissections of the thoracic aorta not due to trauma, \\<50yo\n* Other congenital heart disease (e.g., Tetralogy of Fallot, coarctation)\n\nExclusion Criteria:\n\n* Inability of the patient, parent or guardian to give consent.\n* Unwillingness to provide a blood or buccal specimen.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "stdAges": [
            "CHILD",
            "ADULT",
            "OLDER_ADULT"
          ],
          "studyPopulation": "The cohort consists of patients with conditions related to genetically-induced thoracic aortic aneurysms.",
          "samplingMethod": "NON_PROBABILITY_SAMPLE"
        },
