            "description": "Blood for PPCA gene mutation and AAV2 and AAV8 antibody titer"
          },
          "enrollmentInfo": {
            "count": 3,
            "type": "ACTUAL"
          }
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Mean, median and standard deviation of age distribution of patients with galactosialidosis.",
              "description": "The clinical and demographic data will be tabulated and analyzed for age distribution and disease manifestations with a goal of defining eligibility criteria for future therapeutic protocols.",
              "timeFrame": "At enrollment"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Number and type of PPCA gene mutations in patients with galactosialidosis.",
              "description": "The genotyping data will be tabulated and analyzed to determine the spectrum of mutations that result in the late infantile form of galactosialidosis.",
              "timeFrame": "At enrollment"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Individuals with suspected or confirmed molecular diagnosis of galactosialidosis who are ≥ 6 months of age.\n\nExclusion Criteria:\n\n* Individuals with a lysosomal storage disorder who have been shown to have a mutation in a gene other than that encoding PPCA.",
