        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "We postulate that with the new generation of CT scanners, MR imaging is not needed to rule out significant injuries. We hope to show that CT alone can be used to clear the cervical spine in obtunded trauma patients.",
              "description": "One hundred ninety-seven patients had their collars removed and CS cleared at a mean of 3.3 days. Removal of CS precautions in OBTPs with gross movement of all extremities is safe and efficacious if CT CS is negative for injury. Supplemental MRI CS is not needed in this patient population. Key Words: Magnetic resonance imaging, Computed tomography, Cervical",
              "timeFrame": "2 years"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Subjects will include all patients (including children) after blunt trauma in whom cervical spine injury has not been ruled out admitted to MetroHealth Medical Center from 10/1/2004-9/30/2006.\n\nExclusion Criteria:\n\n* We are excluding patients with an obvious neurologic deficit attributable to the cervical spine.\n* We are excluding patients with abnormalities of the cervical spine that are identified on either plain films or CT.\n* We are also excluding those patients in whom the cervical spine can be cleared clinically due to normal mental status.",
          "healthyVolunteers": false,
