          "interventions": [
            {
              "type": "DEVICE",
              "name": "ITBS",
              "description": "We will use a coil called Cool-6000 A/P to conduct real and sham control. This coil will be placed on the scalp of older adults. The iTBS protocol will begin with a 2-s burst train (totally 30 pulses), repeating every 10 s. Each burst train will consist of 10 triplet pulses with an inter-burst interval of 0.16 s, thus the triplets fire at a rate of 5 Hz. ITBS parameters will include three continuous pulses at 50 Hz repeated at 5 Hz (2s on, 8s off) for a total of 600 pulses.\n\nWe will administer two rounds of iTBS per treatment day, with a 15-minute interval between the two sessions. In total, each participant will receive 1,200 stimuli during a single-session iTBS, totaling for 14 days. Each treatment session will last for about 30 minutes. Intermittent θ-burst stimulation intensity will be set at 70% of the resting motor threshold.",
              "armGroupLabels": [
                "Left DLPFC",
                "Sham"
              ]
            }
          ]
