          "briefTitle": "Exploring Indications and Practices of Administering Artificial Hydration to Terminal Cancer Patients in Taiwan",
          "officialTitle": "Exploring Indications and Practices of Administering Artificial Hydration to Terminal Cancer Patients and Establishing Clinical Consensus Guideline in Taiwan"
        },
        "statusModule": {
          "statusVerifiedDate": "2024-03",
          "overallStatus": "UNKNOWN",
          "lastKnownStatus": "RECRUITING",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
            "date": "2024-08-15",
