        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Clinical Performance and Value (CPV)-measured variation in Assessment",
              "description": "Measuring the rates of ordering prostate biopsy with proper assessment, recognition, and management of prostate cancer risks in patients with different PSA levels, a negative previous prostate biopsy, and an elevated PI-RADS score.",
              "timeFrame": "[4 months]"
            },
            {
              "measure": "CPV-measured change in treatment Quality",
              "description": "Measure of the difference in quality of overall diagnostic scores between control physicians using standard of care diagnostic tools and intervention physicians using the MyProstateScore test.",
              "timeFrame": "[4 months]"
            },
            {
              "measure": "CPV-measured variation in evidence based decisions between control and intervention arms",
              "description": "Measure of the difference in number of evidence-based decisions made by intervention physicians versus control physicians, while controlling for physician and practice characteristics, between rounds 1 and 2.",
              "timeFrame": "[4 months]"
            },
            {
              "measure": "CPV-measured variation in evidence based decisions between intervention arms",
              "description": "Measure the differences in amount of evidence-based decisions made by intervention group one physicians versus intervention group two physicians to assess whether the choice to order the MyProstateScore test impacts the frequency of prostate biopsies and overall patient care and outcomes.",
              "timeFrame": "[4 months]"
            },
            {
              "measure": "CPV-measured rate of adoption for MyProstateScore",
              "description": "Rate of adoption of the MyProstateScore test after receiving educational materials on the benefits of testing in patients who are at risk.",
              "timeFrame": "[4 months]"
            },
            {
              "measure": "CPV-measured differences in cost of care between control and intervention arms",
              "description": "Difference in the cost of care between control and intervention physicians (Cost will be calculated by measuring differential rates of medical interventions/levels of care selected by each arm, and multiplying by Medicare reimbursement rates for these interventions, and/or by modeling the incidence of expected complications and calculating associated costs per above).",
              "timeFrame": "[4 months]"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Board-certified urologists for at least two years\n* Averaging at least 20 hours per week of clinical and patient care duties over the last six months\n* Routinely evaluate patients at risk for prostate cancer in their practice\n* Practicing in the U.S.\n* English speaking\n* Access to the internet\n* Informed, signed and voluntarily consented to be in the study\n\nExclusion Criteria:\n\n* Non-English speaking\n* Unable to access the internet\n* Not practicing in the U.S.\n* Not averaging at least 20 hours per week of clinical or patient care duties over the last six months\n* Previous exposure to the MyProstateScore test\n* Do not voluntarily consent to be in the study",
