          "briefTitle": "Measuring Health Related Quality of Life in AYAs",
          "officialTitle": "Optimizing Health Related Quality of Life Measurement in Adolescent and Young Adult Oncology:",
          "acronym": "PROMIS AYA"
        },
        "statusModule": {
