          ],
          "studyPopulation": "Adolescents or young adults diagnosed with cancer (except for basal cell skin cancer) at 15 to 39 years of age. Patients who have met with a reproductive specialist or who have indicated a pre-treatment desire to have biological children will be prioritized in recruitment.",
          "samplingMethod": "NON_PROBABILITY_SAMPLE"
