          "briefTitle": "Effectiveness and Safety of Percutaneous Adhesiolysis Using Rac'z Catheter Versus Navi Catheter in Management of Failed Back Surgery Syndrome",
          "officialTitle": "Effectiveness and Safety of Percutaneous Adhesiolysis Using Rac'z Catheter Versus Navi Catheter in Management of Failed Back Surgery Syndrome"
        },
        "statusModule": {
          "statusVerifiedDate": "2025-02",
