        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "numerical rating scale",
              "description": "The VAS score was used that has 0-10 points. The 0 point represents the painless state and a score from 1 to 3 points represents mild pain, from 4 to 6 points represents moderate pain and from 7 to 10 points represents severe pain.",
              "timeFrame": "12 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Oswestry Disability Index (ODI)",
              "description": "0 - 100% disability; minimal disability = 0% to either bed-bound or exaggerating symptoms = 100%)",
              "timeFrame": "12 month"
            },
            {
              "measure": "pregabalin consumption",
              "description": "amount of pregabalin consumed by the patient per day",
              "timeFrame": "12 month"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Patients with history of lumbar surgery of at least 6 months duration in the past.\n* Patients over the 18 years of age.\n* History of persistent function-limiting lower extremity pain aggravated by \"dural tug\" (observed when the patient, sitting on the exam table with legs stretched out, bends forward, bringing on the back pain) with or without low back pain of at least 6 months duration after failure of conventional conservative management in most patients including NSAIDS, muscle relaxants (tizanidine, magnesium sulphate) and pregabalin.\n* Patients who are competent to understand the study protocol and provide voluntary, written informed consent and participate in outcome measurements.\n\nExclusion Criteria:\n\n* Unstable or heavy opioid use.\n* Uncontrolled psychiatric disorders.\n* Uncontrolled medical illness.\n* Any conditions that could interfere with the interpretation of the outcome assessments.\n* Pregnant or lactating women.\n* Patients with a history or potential for adverse reaction(s) to local anaesthetics or steroid.",
          "healthyVolunteers": false,
