          "briefTitle": "The Effect of Pregabalin on the Spinal Anesthesia",
          "officialTitle": "The Effect of Pregabalin on the Spinal Anesthesia: Randomized Controlled Placebo Study"
        },
        "statusModule": {
          "statusVerifiedDate": "2016-05",
          "overallStatus": "COMPLETED",
