        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "PRINCIPAL_INVESTIGATOR",
            "investigatorFullName": "Younghoon Jeon",
            "investigatorTitle": "Professor",
            "investigatorAffiliation": "Kyungpook National University Hospital"
          },
          "leadSponsor": {
            "name": "Kyungpook National University Hospital",
            "class": "OTHER"
          }
        },
        "descriptionModule": {
          "briefSummary": "Pregabalin, an anticonvulsant is widely used for treatment of neuropathic pain. Recently, it was reported that premedication of pregabalin before general anesthesia is effective to reduce postoperative pain. Up to date, there is no study about the effect of premedication of pregabalin on the spinal anesthesia. Therefore, in this study, investigators investigate the effect of premedication of pregabalin on the spinal anesthesia.",
          "detailedDescription": "In this study, investigators investigate the effect of premedication of pregabaline 150 mg on the spinal anesthesia. Two hours before spinal anesthesia, placebo pill was administered to patients in the group C and pregabalin 150 mg was administered to patients in the group P, respectively. Time for the onset of blockade, cephalad level of analgesia and duration of analgesia were measured."
        },
        "conditionsModule": {
          "conditions": [
