        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "onset of spinal anaesthesia",
              "description": "seventy participants undergoing elective total knee arthroplasty under spinal anesthesia half of them took placebo and the other half took 150 mg pregabalin two hours before the procedure and calculate the time from the base line to the onset of anesthesia.\n\nOur primary outcome is to assess the onset of spinal anesthesia.\n\nto detect the onset of spinal anaesthesia",
              "timeFrame": "three months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "recovery time",
              "description": "Recovery time from the sensory blockade (2-dermatome regression of anesthesia from the maximum level).",
              "timeFrame": "three months"
            },
            {
              "measure": "motor block duration",
              "description": "the time for return to Bromag 2 (the patient is able to move knees and ankles).",
              "timeFrame": "three months"
            },
            {
              "measure": "postoperative analgesia",
              "description": "• Postoperative pain will be assessed by the patient using the visual analog scale in the first 24 hour(VAS, 0=no pain; 10=worst possible pain) every 2 hours up to 24 hours after the operation.",
              "timeFrame": "three months."
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* the ages of 40 and 70 years\n* height 155-170 cm\n* American Society of Anesthesiologists grade I or II .\n* patients underwent total knee arthroplasty under spinal anesthesia\n\nExclusion Criteria:\n\n* patients known to be allergic to any medicines.\n* patients had a history of drug or alcohol abuse.\n* patients were taking opioids or sedative medications,\n* patients Inability to communicate with investigators to evaluate the postoperative pain\n* patients were in need for postoperative ICU hospitalization .\n* patients had a history of psychiatric conditions.\n* Patients with a history of taking pregabalin or gabapentin .",
