        },
        "descriptionModule": {
          "briefSummary": "Clinical study with Lyrica (pregabalin) in patients suffering from epilepsy. This drug is used as adjunctive therapy with one or more antiepileptics. Lyrica has potential to reduce seizure frequency.",
          "detailedDescription": "\\- Included all adult patients with partial seizures and without contraindications according to Summary of Product Characteristics (SmPC)."
        },
        "conditionsModule": {
          "conditions": [
            "Neuralgia",
            "Epilepsy"
          ],
          "keywords": [
            "lyrica pregabalin epilepsy partial seizures"
          ]
        },
        "designModule": {
          "studyType": "OBSERVATIONAL",
          "designInfo": {
            "observationalModel": "COHORT",
            "timePerspective": "PROSPECTIVE"
          },
          "enrollmentInfo": {
            "count": 286,
            "type": "ACTUAL"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Lyrica",
              "description": "Adult patients with partial seizures (type of epilepsy). Inclusion criteria according to Summary of Product Characteristics",
              "interventionNames": [
                "Drug: Lyrica (pregabalin)"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "Lyrica (pregabalin)",
              "description": "The daily dose may range from 150mg to 600mg, administered as two single doses. The treatment should be started with 150mg daily dose (2x75mg). Depending on response and tolerability after 7 days may the dose be increased to 300mg/day (2x150mg) and after further 7 days to maximum dose 600mg/day (2x300mg)",
              "armGroupLabels": [
                "Lyrica"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Percentage of Participants With a 50 Percent or Greater Reduction From Baseline in 28 Day Partial Seizure Frequency",
              "description": "Responder rate was defined as the percentage of participants with at least a 50% reduction in 28-day partial seizure frequency from baseline during the maintenance phase (Week 4 - Week 16). The percent change in partial seizure frequency in the maintenance phase was the change from baseline in partial seizure frequency \\* 100, divided by the partial seizure frequency at the baseline visit.",
              "timeFrame": "Baseline through week 16 or early termination (ET)"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Percentage Change From Baseline in 28 Day Partial Seizure Frequency at Final Visit",
              "description": "The partial seizure frequency for the baseline period was the total number of partial seizures recorded for that period at Visit 0 (week 0). For each participant's final visit, the 28 day partial seizure frequency equals total number of partial seizures since the last visit \\* 28 divided by total number of days since the last visit. For percent change from baseline: change from baseline in partial seizure frequency\\*100 divided by partial seizure frequency at baseline visit.",
              "timeFrame": "Baseline and week 16 or ET"
            },
            {
              "measure": "Number of Participants With no Seizures (Partial or Other) During the Last 4 Weeks in the Study",
              "description": "Participants were regarded as seizure-free if no seizures (partial or other) were reported for the participant during the last 4 weeks in the study.",
              "timeFrame": "Week 4 through week 16 or ET"
            },
            {
              "measure": "Change From Baseline in Visual Analog Scale of Anxiety (VAS-A) Scores at Week 4 and Final Visit",
              "description": "VAS-A consists of a visual analog scale ranging from, 0 mm (no anxiety) to 100 mm (extreme anxiety).",
              "timeFrame": "Baseline, week 4 and week 16 or ET"
            },
            {
              "measure": "Number of Participants With Categorical Scores on Clinical Global Impression of Severity (CGI-S)",
              "description": "CGI-S: 7-point clinician rated scale to assess severity of participant's current illness state; range: 1 (normal - not ill at all) to 7 (among the most extremely ill patients). Higher score = more affected.",
              "timeFrame": "Baseline"
            },
            {
              "measure": "Number of Participants With Change in Clinical Global Impression of Severity (CGI-C) From Baseline at Final Visit",
              "description": "The CGI-C scale measures a physician's global impression of a participant's clinical condition at final visit in terms of change relative to the start of treatment (CGI-C).\n\nAt final visit, the participants CGI-C will be categorized into a three point scale as: improvement: CGI response of very much improved, much improved or minimally improved; no change: CGI response of no change; worsening: CGI response of very much worse, much worse or minimally worse.",
              "timeFrame": "Week 16 or ET"
            },
            {
              "measure": "Change From Baseline in Medical Outcome Study (MOS) Sleep Scale Sub-scores at Week 16 or ET",
              "description": "MOS: participant rated questionnaire, assess sleep quality and quantity. Consists of 9-item overall sleep problems index (length of time to fall asleep, how many hours of sleep each night during past 4 weeks); 7 subscales rated 1 (all the time) to 6 (none of the time): sleep disturbance, snoring, awaken short of breath (SOB) or with a headache, somnolence adequacy, and sleep quantity. Transformed scores (actual raw score minus lowest possible score divided by possible raw score range multiplied by 100); sub-scales total score range= 0-100; higher score indicates greater intensity of attribute.",
              "timeFrame": "Baseline and week 16 or ET"
            }
          ],
          "otherOutcomes": [
            {
              "measure": "Number of Participants With Concomitant Drug Treatments",
              "description": "Concomitant drug (any drug other than, and in addition to, the study drug) taken for any period of time during the study.",
              "timeFrame": "Baseline through Week 16 or ET"
            },
            {
              "measure": "Number of Participants With Concomitant Co-morbidities",
              "description": "Participants who had a concomitant co-morbidity during the study for any period of time from baseline through to Week 16 (Final Visit); participants with more than one concomitant co-morbidity were counted for each of the co-morbidity classes applicable.",
              "timeFrame": "Baseline through week 16 or ET"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Adult patients with partial seizures.\n\nExclusion Criteria:\n\n* Contraindications according to Summary of Product Characteristics (SmPC).",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ],
          "studyPopulation": "* Adult patiens with partial seizures.\n* Other inclusion criteria according to Summary of Product Characteristics (SmPC).",
          "samplingMethod": "PROBABILITY_SAMPLE"
        },
