        "outcomeMeasuresModule": {
          "outcomeMeasures": [
            {
              "type": "PRIMARY",
              "title": "Percentage of Participants With a 50 Percent or Greater Reduction From Baseline in 28 Day Partial Seizure Frequency",
              "description": "Responder rate was defined as the percentage of participants with at least a 50% reduction in 28-day partial seizure frequency from baseline during the maintenance phase (Week 4 - Week 16). The percent change in partial seizure frequency in the maintenance phase was the change from baseline in partial seizure frequency \\* 100, divided by the partial seizure frequency at the baseline visit.",
              "populationDescription": "The modified full analysis set (MFAS) included all participants who received at least 1 dose of the study drug and who had at least one baseline seizure. Participants who discontinued during first 4 weeks titration phase were regarded as missing and were excluded from the analysis.",
              "reportingStatus": "POSTED",
              "paramType": "NUMBER",
              "dispersionType": "95% Confidence Interval",
              "unitOfMeasure": "Percentage of participants",
              "timeFrame": "Baseline through week 16 or early termination (ET)",
              "groups": [
                {
                  "id": "OG000",
                  "title": "Pregabalin",
                  "description": "Pregabalin (Lyrica) at a dose ranging from 150 milligrams (mg) to 600 mg administered as two single doses, daily until Week 16."
