          },
          "briefTitle": "Pre- and Post-Treatment Investigation of B12 and Folic Acid (Folate) Levels in Patients Receiving Antiepileptic (Anticonvulsant) Treatment for Neuropathic Pain",
          "officialTitle": "Pre- and Post-Treatment Investigation of B12 and Folic Acid (Folate) Levels in Patients Receiving Antiepileptic (Anticonvulsant) Treatment for Neuropathic Pain: Retrospective Study"
        },
        "statusModule": {
          "statusVerifiedDate": "2025-05",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
            "date": "2025-06-15",
            "type": "ACTUAL"
          },
          "primaryCompletionDateStruct": {
            "date": "2025-06-25",
