        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Case group.",
              "description": "Patients with genetically proven familial hypocholesterolemia, who will accept to participate in this study and have been treated for this pathology since 1990 in the Department of Gastroenterology and Paediatric Nutrition (Pr Peretti) and continue their follow-up into adulthood at the GHE (Groupement Hospitalier Est) in Lyon in the endocrinology-nutrition service (Pr Moulin).\n\nThey may be girl/woman or boy/man over 6 years of age and over 12 kg at the time of inclusion (age required for cooperation on macular pigment measurement), agreeing to participate in the study with clear and informed consent. These patients are covered by social security.",
              "interventionNames": [
                "Biological: Characterization of carotenoid status and plasma levels of oxidative stress markers in patients (case group only)"
              ]
            },
            {
              "label": "Control group.",
              "description": "The control group consists of children over 6 years old or adult patients, followed routinely in the ophthalmology department of the Edouard Herriot Hospital, Lyon (Pr Kodjikian) not suffering from genetic hypocholesterolemia and requiring a fundus examination as part of the usual follow-up of their ocular pathology, if this pathology does not interfere with the macular pigment density. An additional measurement of the macular pigment density will be made during this examination. The control group is only needed for the macular pigment analysis. No control group is considered for the characterization of plasma lutein and zeaxanthin deficiency and for the analysis of oxidative stress, so there will be no additional blood sampling for control patients.",
              "interventionNames": [
                "Other: Characterization, evaluation and comparison of macular pigment density"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BIOLOGICAL",
              "name": "Characterization of carotenoid status and plasma levels of oxidative stress markers in patients (case group only)",
              "description": "Carotenoid status will be determined by measuring plasma and erythrocyte concentrations of lutein and zeaxanthin obtained during an annual blood draw. These molecules will be analyzed by high performance liquid chromatography.\n\nThe oxidative stress markers will be measured, in the blood sample already collected, thanks to specific assay kits: Erythrocyte reduced glutathione, Superoxide dismutase (SOD), Glutathione peroxidase (GPx), Plasma and erythrocyte malondialdehyde, Plasma vitamin C, Plasma oxidized cholesterol, F2-isoprostanes.\n\nThis study does not result in any change in patient management, but requires the collection of an additional volume of blood (14 ml of study-specific blood) during the annual blood draw performed as part of routine patient follow-up.",
              "armGroupLabels": [
                "Case group."
              ]
            },
            {
              "type": "OTHER",
              "name": "Characterization, evaluation and comparison of macular pigment density",
              "description": "The macular pigment optical density (OD) will be determined by an additional photograph during the fundus usually performed for annual follow-up through two-wavelength autofluorescence imaging. Indeed, the measurement of the optical density consists of an additional post-examination analysis of additional retinal images obtained during the fundus performed for the patients' ophthalmologic follow-up.",
              "armGroupLabels": [
                "Control group."
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "The principal outcome measure is the macular pigment optical density (OD)",
              "description": "The macular pigment optical density (OD) will be determined by an additional photograph during the fundus usually performed for annual follow-up through two-wavelength autofluorescence imaging. This imaging method provides a profile of autofluorescence distribution calculated using a gray intensity scale in the center of the macula and along the horizontal and vertical meridians. The optical density of the macular pigment is then expressed as the logarithm of the ratio of the peri-oval/foveal excitation spectra symbolized by the acronym \"DU\" (\"Density Unit\"). Indeed, in autofluorescence, the lipofuscin chromophores are generally excited with two wavelengths: a first one which is located in the blue spectral region where the absorption band of the lipofuscin overlaps that of the macular pigments, and a second one which is always located in the absorption region of the lipofuscin but outside the absorption range of the macular pigments. Thus, excitation by the first (green) light causes",
              "timeFrame": "The optical density measurement will be performed, in addition to the usual patient follow-up tests, during a single visit to the ophthalmology department on a date chosen by the patient."
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Genetically proven family hypocholesterolemia patients,\n* Patients systematically monitored in the Gastroenterology and Paediatric Nutrition department of the Women's Hospital Mother Child of Lyon or in the adult endocrinology department of the GHE (Louis Pradel Hospital),\n* Girl/woman or boy/man over 6 years and over 12 kg at the time of inclusion (age required for cooperation on macular pigment measurement),\n* No objection from the patient or their parents/legal tutors in the case of a minor patient,\n* Patient covered by social security.\n\nExclusion Criteria:\n\n* Allergy to local anesthetics (especially xylocaine)\n* Mydriatic allergy\n* Person participating in another research with an exclusion period still in progress at pre-inclusion\n* Person subject to a safeguard measure.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "6 Years",
          "maximumAge": "50 Years",
          "stdAges": [
            "CHILD",
            "ADULT"
          ],
          "studyPopulation": "This study relates to adults or children over 6 years of age (cooperation necessary to perform the fundus) with primary intestinal hypocholesterolemia.\n\nThe control population comprising major control patients under the age of 50 (limit the risk of age-related macular degeneration - AMD) or under age over 6 (cooperation necessary to perform OF) routinely monitored in the service of ophthalmology requiring a fundus examination as part of their usual follow-up.",
          "samplingMethod": "NON_PROBABILITY_SAMPLE"
        },
        "contactsLocationsModule": {
          "overallOfficials": [
            {
              "name": "Peretti Noël, Pr",
              "affiliation": "Hospices Civils de Lyon",
              "role": "PRINCIPAL_INVESTIGATOR"
            }
