[{"role": "assistant", "content": "", "tool_calls": [{"id": "call_k2mkx0nh", "type": "function", "function": {"name": "clinicaltrialsgov-mcp-server_clinicaltrials_list_studies", "arguments": "{"query":{"cond":"apartment"},"pageSize":10}"}}]}, {"role": "tool", "content": [{"type": "text", "text": "{
  "studies": [
    {
      "protocolSection": {
        "identificationModule": {
