        "descriptionModule": {
          "briefSummary": "The progression of neurodegenerative disorders and the increasing number of elderly people intensifies the need of institutional care, which contrasts with the desire of most elderly and patients to live independently at home. The rapid evolution of assistive technology offers new possibilities in providing medical professionals preventive services in real-time. Therefore, the main focus of this study is on the individual sensors and how they can be combined to one unobtrusive system to assess the human behaviour and daily activities during day and night in an instrumented apartment in healthy participants.",
          "detailedDescription": "The higher prevalence of age-associated neurodegenerative disorders (e.g. Parkinson, Alzheimer), is in line with a steady increase of the average life expectancy in Switzerland. With the progression of neurodegenerative disorders and the increasing number of elderly people, the need for institutional care intensifies, which contrasts with the desire of most elderly and patients to live independently. The rapid evolution of assistive technology offers new possibilities in providing medical professionals preventive services in real-time. An extended stay in the hospital could influence independent ageing negatively and thus, monitoring has great potential to prevent critical events. In this study, the main focus is on the individual sensors and how they can be combined to one unobtrusive system. In addition, to get an understanding which parameters of the sensors are important and how the data can be extracted and processed (algorithms). Therefore, the aim of this study is to validate the accuracy to assess human behaviour and daily activities during day and night by unobtrusive sensors in an instrumented apartment in healthy participants."
        },
        "conditionsModule": {
          "conditions": [
            "Neurodegenerative Diseases",
            "Activities of Daily Living",
            "Aging"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "NA"
          ],
          "designInfo": {
            "allocation": "NA",
            "interventionModel": "SINGLE_GROUP",
            "interventionModelDescription": "Single-center prospective non-inferiority study",
            "primaryPurpose": "PREVENTION",
            "maskingInfo": {
              "masking": "NONE"
            }
          },
          "enrollmentInfo": {
            "count": 104,
            "type": "ACTUAL"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Experimental_Arm",
              "type": "EXPERIMENTAL",
              "description": "Assessment of behavior during day and night by unobtrusive sensors",
              "interventionNames": [
                "Other: Monitoring by unobtrusive sensors"
              ]
            }
          ],
          "interventions": [
            {
              "type": "OTHER",
              "name": "Monitoring by unobtrusive sensors",
              "description": "During the study the behavior of daily activities will be monitored by unobstructive sensors. Most of the sensors will be mounted on the wall or on furniture with direct sight to the participant and thus will not have any physical contact, except some wearables during the stay in the apartment and at home (e.g. watch, mobile polysomnography).",
              "armGroupLabels": [
                "Experimental_Arm"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Heart rate (Vital parameters)",
              "description": "The heart rate will be continuously measured by pressure sensors, radar sensors, infrared camera, galvanic sensor and polysomnography (gold standard).",
              "timeFrame": "1 Week / Continuously"
            },
            {
              "measure": "Respiration rate (Vital parameters)",
              "description": "The respiration rate will be continuously measured by pressure sensors, radar sensors, infrared camera, galvanic sensor and polysomnography (gold standard).",
              "timeFrame": "1 Week / Continuously"
            },
            {
              "measure": "Oxygen saturation (Vital parameters)",
              "description": "The oxygen saturation will be continuously measured by pressure sensors, radar sensors, infrared camera, galvanic sensor and polysomnography (gold standard).",
              "timeFrame": "1 Week / Continuously"
            },
            {
              "measure": "Systolic / Diastolic blood pressure (Vital parameters)",
              "description": "The blood pressure will be continuously measured by pressure sensors, radar sensors, infrared camera, galvanic sensor and polysomnography (gold standard).",
              "timeFrame": "1 Week / Continuously"
            },
            {
              "measure": "Skin conductance (Vital parameters)",
              "description": "The skin conductance will be continuously measured by pressure sensors, radar sensors, infrared camera, galvanic sensor and polysomnography (gold standard).",
              "timeFrame": "1 Week / Continuously"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "3D Model (Coordinates of the joints over time) of the participant in the apartment (Movement parameters)",
              "description": "The pose will be assessed continuously by pressure sensors, radar sensors, accelerometer, gyroscope, motion tracking (gold standard), lidar sensors, piir sensors.",
              "timeFrame": "1 Week / Continuously"
            }
          ],
          "otherOutcomes": [
            {
              "measure": "Usability",
              "description": "The usability of the sensor system will be assessed by the System usability scale (SUS). The score range is between 0 and 100, whereas the higher score means higher usability.",
              "timeFrame": "Each day / 7x"
            },
            {
              "measure": "Doors open and closed (Activities of daily living)",
              "description": "Unit: 1 open, 0 closed.",
              "timeFrame": "1 Week / Continuously"
            },
            {
              "measure": "Power used - Power Plugs (Activities of daily living)",
              "description": "Unit: Watt.",
              "timeFrame": "1 Week / Continuously"
            },
            {
              "measure": "Temperature (Activities of daily living)",
              "description": "Unit: Degree Celsius.",
              "timeFrame": "1 Week / Continuously"
            },
            {
              "measure": "Relative Humidity (Activities of daily living)",
              "description": "Unit: Percent - Relative to a maximum humidity given the same temperature.",
              "timeFrame": "1 Week / Continuously"
            },
            {
              "measure": "Brightness (Activities of daily living)",
              "description": "Unit: Lux.",
              "timeFrame": "1 Week / Continuously"
            },
            {
              "measure": "Accelerometer - Wearable (Activities of daily living)",
              "description": "Unit: m/s\\^2.",
              "timeFrame": "1 Week / Continuously"
            },
            {
              "measure": "Electrocardiography (ECG) - Wearable (Activities of daily living)",
              "description": "Unit: Component of the ECG (QRS Complex).",
              "timeFrame": "1 Week / Continuously"
            },
            {
              "measure": "Cognition 1",
              "description": "Cognition will be assessed by the Montreal Cognitive Assessment (MoCA). Scores of the MoCA range from 0 to 30, with a score of 26 and higher generally considered normal.",
              "timeFrame": "Measured on the first day / 1x"
            },
            {
              "measure": "Cognition 2",
              "description": "Cognition will be assessed by the Mini-Mental State Examination (MMSE). Scores of the MMSE range from 0 to 30, with a score of 25 and higher generally considered normal.",
              "timeFrame": "Measured on the first day / 1x"
            },
            {
              "measure": "Health-related quality of life",
              "description": "Health-related quality of life will be assessed by the EuroQol (EQ-5D-5L).The EQ-5D-5L comprises five questions on mobility, self-care, pain, usual activities, and psychological status. The questions have five possible answers for each item (no problems - unable to).",
              "timeFrame": "Measured on the first and last day / 2x"
            },
            {
              "measure": "Sleep quality",
              "description": "Sleep quality will be assessed by the SF A/R. The inventory estimates the total sleep duration (calculated from items 'bedtime in the evening' and 'wake-up time in morning'), time awake after sleep onset, and sleep onset latency (5-point Likert scale).",
              "timeFrame": "Each day / 7x"
            },
            {
              "measure": "Chronotype",
              "description": "The Chronotype will be assessed by the D-MEQ. The D-MEQ scores range between 13 and 86. High sum scores (59-86) are associated to morningness, while lower scores point to eveningness (16-41).",
              "timeFrame": "Measured on the first day / 1x"
            },
            {
              "measure": "Depression 1",
              "description": "Depression will be assessed by the Geriatric Depression Scale (GDS). The inventory has 15 questions (yes/no). Scores of 0-4 are considered normal and 12-15 indicate severe depression.",
              "timeFrame": "Measured on the first day / 1x"
            },
            {
              "measure": "Depression 2",
              "description": "Depression will be assessed by the Beck Depression Inventory (BDI). The inventory has 21 questions (yes/no). Scores of 1-10 are considered normal and over 40 indicate severe depression.",
              "timeFrame": "Measured on the first day / 1x"
            },
            {
              "measure": "Physical activity",
              "description": "Physical activity will be assessed by the International Physical Activity Questionnaire (IPAQ). The IPAQ assesses the time spent on walking, doing moderate-intensity and vigorous-intensity activity within the domains of work, transportation, domestic and gardening (yard) activities, and leisure-related activities.",
              "timeFrame": "Measured on the first day / 1x"
            },
            {
              "measure": "Grip strength",
              "description": "Grip strength will be assessed by a dynamometer.",
              "timeFrame": "Measured on the first day / 1x"
            },
            {
              "measure": "Fall risk",
              "description": "Fall risk will be assessed by the Time Up and Go Test (TUG).",
              "timeFrame": "Measured on the first day / 1x"
            },
            {
              "measure": "Gait and balance",
              "description": "Gait and balance will be assessed by the Tinetti Balance and Gait Test (POMA).",
              "timeFrame": "Measured on the first day / 1x"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Written informed consent\n* Aged ≥18 years\n* German speaking\n\nExclusion Criteria:\n\n* Infected by multidrug-resistant bacteria according to current medical history\n* Incontinence",
