          "briefTitle": "The Incidence of Adjacent Synchronous Ipsilateral Infiltrating Carcinoma and/or DCIS in Patients Diagnosed With Intraductal Papilloma Without Atypia or Flat Epithelial Atypia by Core Needle Biopsy",
          "officialTitle": "The Incidence of Adjacent Synchronous Ipsilateral Infiltrating Carcinoma and/or DCIS in Patients Diagnosed With Intraductal Papilloma Without Atypia or Flat Epithelial Atypia by Core Needle Biopsy"
        },
        "statusModule": {
          "statusVerifiedDate": "2025-09",
          "overallStatus": "COMPLETED",
