          }
        },
        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "PRINCIPAL_INVESTIGATOR",
            "investigatorFullName": "Faina Nakhlis, MD",
            "investigatorTitle": "Faina Nakhlis, MD",
