        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "PRINCIPAL_INVESTIGATOR",
            "investigatorFullName": "Dr. Sameer Al-Abdi",
            "investigatorTitle": "Consultant Neonatologist",
            "investigatorAffiliation": "King Abdul Aziz General Hospital"
          },
          "leadSponsor": {
            "name": "King Abdul Aziz General Hospital",
