          "officialTitle": "Oblique Sliding K-wire Technique For Controlling Calcaneal Displacement Osteotomy In Flat Foot Correction"
        },
        "statusModule": {
          "statusVerifiedDate": "2025-04",
          "overallStatus": "NOT_YET_RECRUITING",
