          ],
          "designInfo": {
            "allocation": "NA",
            "interventionModel": "SINGLE_GROUP",
            "interventionModelDescription": "using an oblique K-wire technique in controlling Calcaneal displacement during osteotomy in flatfoot correction",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "NONE"
            }
          },
          "enrollmentInfo": {
            "count": 20,
            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Oblique K-wire Control in Calcaneal Osteotomy for Flatfoot Correction",
              "type": "OTHER",
              "description": "oblique K-wire technique in controlling Calcaneal displacement during osteotomy in flatfoot correction",
              "interventionNames": [
                "Procedure: oblique K-wire technique in controlling Calcaneal displacement during osteotomy in flatfoot correction"
              ]
            }
          ],
          "interventions": [
            {
              "type": "PROCEDURE",
              "name": "oblique K-wire technique in controlling Calcaneal displacement during osteotomy in flatfoot correction",
              "description": "Under spinal Anaesthesia , patients will placed in lateral decubitus position. A standard lateral incision will be made over the calcaneus, and the osteotomy site will be exposed. An oblique K-wire will be inserted percutaneously into the posterior calcaneus under fluoroscopic guidance to facilitate the desired displacement. Cannulated screws will then be inserted across the osteotomy site to secure the calcaneal fragment. Post-operative care will include a non-weight bearing protocol for six weeks, followed by gradual weight bearing as tolerated.",
              "armGroupLabels": [
                "Oblique K-wire Control in Calcaneal Osteotomy for Flatfoot Correction"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "assessment of degree of desired displacement",
              "description": "Intra-operative assessment of degree of desired displacement clinical and radiological",
              "timeFrame": "baseline"
            }
