            "class": "NIH"
          },
          "briefTitle": "Testing the Addition of an Anti-cancer Drug, Pembrolizumab, to the Usual Intravesical Chemotherapy Treatment (Gemcitabine) for the Treatment of BCG-Unresponsive Non-muscle Invasive Bladder Cancer",
          "officialTitle": "Phase II Trial of Intravesical Gemcitabine and MK-3475 (Pembrolizumab) in the Treatment of Patients With BCG-Unresponsive Non-Muscle Invasive Bladder Cancer"
        },
        "statusModule": {
          "statusVerifiedDate": "2026-08",
          "overallStatus": "ACTIVE_NOT_RECRUITING",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
            "date": "2020-03-18",
